window.ATRIL.data.fun = [{"id":"FUN-0001","t":"Natureza pro solvendo do cheque (Direito Cambiário)","c":"DIREITO CAMBIÁRIO","co":"DIREITO CAMBIÁRIO","g":["devolução de cheque","discussão sobre quitação de dívida paga com cheque devolvido"],"f":"Fundamentação para afastar a quitação quando o cheque é devolvido.","b":"Possui o cheque natureza pro solvendo, ficando a eficácia liberatória condicionada à efetiva compensação (STJ, REsp nº 1.094.571/SP). Não elide o recibo vinculado a cheque devolvido a presunção de inadimplemento. Detém a quitação (art. 320, CC) presunção meramente relativa.","e":["emissão de cheque","devolução sem compensação","recibo vinculado ao cheque"],"l":["compensação efetiva do título"],"x":[]},{"id":"FUN-0002","t":"Compensação de cheque por cópia (Direito Bancário)","c":"DIREITO CAMBIÁRIO","co":"DIREITO CAMBIÁRIO","g":["compensação de cheque fraudado mediante cópia"],"f":"Fundamentação para responsabilização do banco sacado.","b":"Constitui negligência bancária a compensação de cheque mediante simples cópia reprográfica, creditando valor a terceiro estranho à relação (Súmula 479 STJ), impondo ressarcimento material.","e":["compensação por cópia","crédito a terceiro"],"l":["culpa exclusiva do correntista"],"x":[]},{"id":"FUN-0003","t":"Justiça gratuita — concessão e suspensão de exigibilidade","c":"DIREITO PROCESSUAL CIVIL — GRATUIDADE","co":"DIREITO DIGITAL E REDES SOCIAIS","g":["concessão de benefício de gratuidade","suspensão de custas e honorários"],"f":"Fundamentação para concessão de gratuidade e efeitos processuais.","b":"A análise dos autos demonstra os pressupostos da gratuidade da justiça, razão pela qual concedo o benefício à parte requerente. Havendo obrigação sucumbencial cuja exigibilidade deva ser suspensa, os efeitos devem ser explicitados conforme o art. 98, § 3º, do CPC.","e":["elementos probatórios de vulnerabilidade","concessão do benefício"],"l":["ausência de vulnerabilidade comprovada"],"x":[{"campo":"categoria","razao":"Tema processual deslocado da categoria de redes sociais.","origem":"DIREITO DIGITAL E REDES SOCIAIS"},{"campo":"Formulação-base","razao":"A suspensão alcança obrigações sucumbenciais, não a exigibilidade do benefício.","origem":"Da análise dos autos verifica-se a presença de elementos probatórios aptos a corroborar a presunção de vulnerabilidade econômica, razão pela qual concede-se à recorrente os benefícios da gratuidade da justiça, cuja exigibilidade fica suspensa em razão da gratuidade da justiça."}]},{"id":"FUN-0004","t":"Suspensão ou bloqueio injustificado de conta profissional (Redes Sociais)","c":"DIREITO DIGITAL E REDES SOCIAIS","co":"DIREITO DIGITAL E REDES SOCIAIS","g":["conta profissional suspensa ou encerrada","ausência de demonstração de violação dos termos de uso","bloqueio que compromete faturamento"],"f":"Fundamentação para reconhecimento de falha na prestação do serviço e dano moral.","b":"Comete falha na prestação do serviço o provedor que suspende ou encerra conta sem demonstrar a violação dos termos de uso (art. 14 do CDC). Quando a conta possui natureza profissional e o bloqueio compromete o faturamento do usuário, ultrapassa a situação o mero dissabor, configurando dano moral.","e":["natureza profissional da conta","bloqueio sem demonstração de infração","comprometimento de faturamento"],"l":["comprovação de violação aos termos de uso"],"x":[]},{"id":"FUN-0005","t":"Invasão de conta por terceiros (Redes Sociais)","c":"DIREITO DIGITAL E REDES SOCIAIS","co":"DIREITO DIGITAL E REDES SOCIAIS","g":["invasão de perfil por hackers/terceiros","falha na segurança da plataforma","exclusão da conta pela plataforma após invasão"],"f":"Fundamentação para responsabilização do provedor por falha de segurança e obrigação de reativação.","b":"Ao armazenar dados e gerenciar contas, assume o provedor o risco da atividade, devendo garantir a segurança e inviolabilidade das informações dos usuários (art. 14, CDC). Configura falha na prestação do serviço a invasão de perfil por terceiros. Constitui fortuito interno a exclusão definitiva da conta pela própria plataforma como consequência da invasão, não afastando a obrigação de reativação.","e":["invasão por terceiros","exclusão ou perda de acesso","risco da atividade"],"l":["culpa exclusiva do consumidor (ex: fornecimento voluntário de senhas)"],"x":[]},{"id":"FUN-0006","t":"Limites na proteção da honra e da imagem (Liberdade de Expressão)","c":"DIREITO DIGITAL E REDES SOCIAIS","co":"DIREITO DIGITAL E REDES SOCIAIS","g":["conflito entre liberdade de expressão/imprensa e direitos da personalidade","publicações difamatórias ou inverídicas"],"f":"Fundamentação para limitação da liberdade de expressão e responsabilização por ofensas.","b":"Não ostenta a liberdade de expressão caráter absoluto, devendo harmonizar-se com a proteção da honra e da imagem (art. 220, caput, e art. 5º, IV, IX e XIV, CF). Limitações incluem compromisso ético com a informação verossímil, preservação dos direitos da personalidade e vedação de veiculação difamatória (STJ, REsp 1.897.338/DF). Direitos fundamentais em conflito demandam ponderação pelo princípio da proporcionalidade (STF, MS 23.452).","e":["publicação ofensiva ou inverídica","violação à honra ou imagem"],"l":["exercício regular do direito de informar com base em fatos verídicos e sem animus injuriandi"],"x":[]},{"id":"FUN-0007","t":"Dever de retratação (Liberdade de Expressão)","c":"DIREITO DIGITAL E REDES SOCIAIS","co":"DIREITO DIGITAL E REDES SOCIAIS","g":["pedido de retificação de publicação ofensiva ou inverídica"],"f":"Fundamentação para determinar a publicação de retratação.","b":"Visa a publicação de retificação mitigar os efeitos da publicidade negativa e restaurar a honra do ofendido perante a coletividade.","e":["ofensa pública","necessidade de restauração da imagem"],"l":["ausência de ofensa ou inveracidade na publicação original"],"x":[]},{"id":"FUN-0008","t":"Limites da responsabilidade da montadora no Recall","c":"DIREITO DO CONSUMIDOR — AUTOMÓVEL","co":"DIREITO DO CONSUMIDOR — AUTOMÓVEL","g":["pedido de indenização por despesas logísticas ou danos morais decorrentes do chamamento","recall sem ocorrência de acidente ou defeito manifesto"],"f":"Fundamentação para afastar indenizações acessórias decorrentes do mero chamamento para recall.","b":"Restrita a gratuidade ao serviço de reparo e substituição de peças (art. 10, § 1º, do CDC), não se estendendo a despesas logísticas autônomas quando inexiste defeito real que impeça a condução. Configura o recall cumprimento de dever legal e medida de proteção à vida do consumidor.","e":["chamamento para recall","ausência de defeito materializado ou acidente","pedido de despesas logísticas/dano moral"],"l":["defeito efetivamente manifestado causando danos antes do reparo"],"x":[]},{"id":"FUN-0009","t":"Vícios redibitórios em veículo usado entre particulares (Compra e Venda)","c":"DIREITO CIVIL — COMPRA E VENDA","co":"DIREITO DO CONSUMIDOR — AUTOMÓVEL","g":["defeito em veículo usado adquirido de particular","veículo com alta quilometragem ou histórico de leilão"],"f":"Fundamentação para afastar a responsabilidade do vendedor por desgastes naturais.","b":"Submete o negócio jurídico firmado exclusivamente entre pessoas físicas ao Código Civil (art. 441). Em veículo com longo tempo de fabricação, alta quilometragem ou histórico notório de leilão, inserem eventuais manutenções atreladas ao desgaste natural no risco assumido pelo comprador. Sujeito o direito de reclamar, quando aplicável o CDC, ao prazo decadencial de 90 dias (art. 26, II e § 3º).","e":["compra e venda entre particulares","veículo antigo ou com alta quilometragem","defeito decorrente de desgaste natural"],"l":["vício oculto pré-existente e de conhecimento do vendedor (má-fé)"],"x":[{"campo":"categoria","razao":"Compra e venda entre particulares não deve receber classificação consumerista automática.","origem":"DIREITO DO CONSUMIDOR — AUTOMÓVEL"}]},{"id":"FUN-0010","t":"Danos em veículos por estrutura da rede elétrica (Energia Elétrica)","c":"DIREITO DO CONSUMIDOR — AUTOMÓVEL","co":"DIREITO DO CONSUMIDOR — AUTOMÓVEL","g":["queda de fios/postes sobre veículos"],"f":"Fundamentação para exigir prova do nexo causal.","b":"Exige a alegação de danos materiais e morais provocados por queda de objeto da rede elétrica sobre veículo demonstração inequívoca do nexo de causalidade (dinâmica do sinistro correlacionada aos registros operacionais da concessionária). Inexistindo indícios mínimos de falha estrutural, resta afastado o dever de indenizar.","e":["dano por equipamento da concessionária","necessidade de prova do nexo causal"],"l":["fortuito externo (ex: temporal atípico, queda de árvore sobre a rede)"],"x":[]},{"id":"FUN-0011","t":"Prescrição da pretensão de cobrança — desconto de dívida prescrita","c":"DIREITO DO CONSUMIDOR — IMOBILIÁRIO","co":"DIREITO DO CONSUMIDOR — IMOBILIÁRIO","g":["desconto em conta bancária de dívida prescrita","discussão sobre exercício regular do direito"],"f":"Fundamentação para reconhecimento de ato ilícito.","b":"Perfaz o prazo quinquenal para cobrança de dívidas líquidas (art. 206, § 5º, I, do CC). Configura a realização de descontos em conta bancária para saldar dívida prescrita ato ilícito, pois excede os limites do exercício regular do direito.","e":["dívida prescrita","desconto em conta"],"l":["dívida não prescrita","consentimento do devedor"],"x":[]},{"id":"FUN-0012","t":"Consumidor por equiparação em vícios construtivos (Vícios Construtivos)","c":"DIREITO DO CONSUMIDOR — IMOBILIÁRIO","co":"DIREITO DO CONSUMIDOR — IMOBILIÁRIO","g":["morador não contratante (ex: familiar, locatário) pleiteando reparação por vício construtivo"],"f":"Fundamentação para reconhecer a legitimidade ativa do morador não contratante.","b":"É consumidor por equiparação o morador que não é contratante formal mas sofre diretamente os efeitos dos defeitos construtivos. Exige a proteção do CDC a condição de vítima do evento de consumo, não a assinatura do instrumento negocial (art. 17, CDC).","e":["morador do imóvel","ausência de vínculo contratual direto com a construtora","danos decorrentes do vício construtivo"],"l":["pessoa que não reside no imóvel e não sofreu os efeitos do vício"],"x":[]},{"id":"FUN-0013","t":"Responsabilidade objetiva do construtor por solidez e segurança (Vícios Construtivos)","c":"DIREITO DO CONSUMIDOR — IMOBILIÁRIO","co":"DIREITO DO CONSUMIDOR — IMOBILIÁRIO","g":["defeitos que afetam a habitabilidade do imóvel"],"f":"Fundamentação para responsabilização da construtora.","b":"Merece interpretação ampla o conceito de solidez e segurança, abrangendo todo defeito que inviabilize condições adequadas de moradia (STJ, AgRg no REsp 399.701/PR). Responde o construtor objetivamente (art. 12, CDC).","e":["vício construtivo","comprometimento da habitabilidade ou segurança"],"l":["mau uso ou falta de manutenção pelo morador","reformas estruturais realizadas por terceiros"],"x":[]},{"id":"FUN-0014","t":"Não presunção de dano moral por vícios construtivos (Vícios Construtivos)","c":"DIREITO DO CONSUMIDOR — IMOBILIÁRIO","co":"DIREITO DO CONSUMIDOR — IMOBILIÁRIO","g":["pedido de dano moral decorrente de vício construtivo"],"f":"Fundamentação para afastar ou exigir prova do dano moral.","b":"Não é presumido o dano moral na ocorrência de vícios de construção, configurado apenas quando houver circunstâncias excepcionais comprovadas (STJ, AgInt no REsp 1.955.291/RS).","e":["vício construtivo","ausência de desdobramentos graves"],"l":["risco de desabamento, insalubridade grave, necessidade de desocupação do imóvel"],"x":[]},{"id":"FUN-0015","t":"Competência dos Juizados para cobrança decorrente de locação (Locação)","c":"DIREITO DO CONSUMIDOR — IMOBILIÁRIO","co":"DIREITO DO CONSUMIDOR — IMOBILIÁRIO","g":["alegação de incompetência do JEC para julgar cobrança de aluguéis/encargos"],"f":"Fundamentação para reconhecer a competência do Juizado Especial.","b":"Não alcança a vedação de ações de despejo as cobranças de quantia certa oriundas de contrato de locação (art. 3º, III, da Lei nº 9.099/95).","e":["ação de cobrança ou execução de aluguéis/encargos","ausência de pedido de despejo"],"l":["cumulação com pedido de despejo (salvo para uso próprio)"],"x":[]},{"id":"FUN-0016","t":"Responsabilidade por taxas condominiais de imóvel novo (Direito Condominial)","c":"DIREITO DO CONSUMIDOR — IMOBILIÁRIO","co":"DIREITO DO CONSUMIDOR — IMOBILIÁRIO","g":["cobrança de condomínio do adquirente antes da entrega das chaves"],"f":"Fundamentação para responsabilizar a construtora.","b":"Recai sobre a construtora a responsabilidade pelo adimplemento de taxas condominiais de imóvel novo até a efetiva entrega das chaves e ciência do condomínio (Tema 886 do STJ). Ilegal o repasse extrajudicial de honorários advocatícios sem previsão em convenção.","e":["imóvel na planta/novo","taxas geradas antes da imissão na posse"],"l":["atraso na entrega das chaves por culpa exclusiva do adquirente (ex: mora no financiamento)"],"x":[]},{"id":"FUN-0017","t":"Multa de fidelidade indevida por falha na prestação do serviço (Telecomunicações)","c":"DIREITO DO CONSUMIDOR — TELECOMUNICAÇÕES","co":"DIREITO DO CONSUMIDOR — TELECOMUNICAÇÕES","g":["cobrança de multa rescisória/fidelidade","rescisão motivada por má prestação do serviço"],"f":"Fundamentação para inexigibilidade da multa de fidelidade.","b":"Vedada a cobrança de multa por rescisão antecipada quando há descumprimento de obrigação contratual ou legal pela prestadora (art. 37, § 2º, II, da Resolução nº 765/2023 da ANATEL). Cabe à operadora o ônus de provar a regularidade do serviço, sendo insuficientes telas sistêmicas internas para demonstrar o regular fornecimento.","e":["rescisão antecipada","falha prévia na prestação do serviço","cobrança de multa"],"l":["comprovação robusta pela operadora da prestação regular do serviço","rescisão imotivada pelo consumidor"],"x":[]},{"id":"FUN-0018","t":"Teoria da aparência em telecomunicações (Telecomunicações)","c":"DIREITO DO CONSUMIDOR — TELECOMUNICAÇÕES","co":"DIREITO DO CONSUMIDOR — TELECOMUNICAÇÕES","g":["contratação de serviços por terceiros usando o nome da operadora","fraude ou oferta enganosa por parceiros/terceiros"],"f":"Fundamentação para responsabilização solidária da operadora.","b":"Configura a cadeia de serviços quando terceiros se utilizam do nome da operadora para oferecer seus serviços. Aplicável a teoria da aparência para responsabilização da operadora, a quem incumbe tomar medidas para coibir o uso indevido de sua marca.","e":["uso da marca/nome da operadora por terceiro","contratação baseada na confiança na marca"],"l":["fraude grosseira perceptível pelo consumidor médio"],"x":[]},{"id":"FUN-0019","t":"Distinção entre ilicitude contratual e dano moral (Telecomunicações)","c":"DIREITO DO CONSUMIDOR — TELECOMUNICAÇÕES","co":"DIREITO DO CONSUMIDOR — TELECOMUNICAÇÕES","g":["cobrança indevida sem maiores repercussões","pedido de dano moral baseado apenas na cobrança"],"f":"Fundamentação para afastar o dano moral em casos de simples cobrança indevida.","b":"Nem toda ilicitude contratual gera, automaticamente, abalo moral indenizável. Resolve a cobrança indevida na esfera patrimonial mediante restituição em dobro (art. 42, parágrafo único, CDC), que já carrega caráter punitivo.","e":["cobrança indevida isolada","ausência de inscrição em cadastro de inadimplentes ou outro desdobramento grave"],"l":["inscrição indevida nos órgãos de proteção ao crédito (dano in re ipsa)","perda de tempo útil/desvio produtivo comprovado"],"x":[]},{"id":"FUN-0020","t":"Preterição de embarque (Transporte Aéreo)","c":"DIREITO DO CONSUMIDOR — TRANSPORTE AÉREO","co":"DIREITO DO CONSUMIDOR — TRANSPORTE AÉREO","g":["passageiro impedido de embarcar em voo contratado (overbooking/preterição)","reacomodação com atraso superior a quatro horas"],"f":"Fundamentação para condenação em compensação financeira e/ou dano moral.","b":"Configura preterição quando o transportador deixa de transportar passageiro que se apresentou para embarque no voo originalmente contratado (art. 22 da Resolução ANAC nº 400/2016). A reacomodação em voo posterior, com atraso superior a quatro horas, não elide a compensação financeira. Integram intercorrências técnicas e operacionais o risco da atividade, caracterizando fortuito interno.","e":["apresentação regular para embarque","impedimento de embarque","atraso superior a 4 horas"],"l":["atraso inferior a 4 horas com reacomodação adequada","culpa do passageiro (ex: apresentação tardia)"],"x":[]},{"id":"FUN-0021","t":"Falha no dever de informação e assistência a vulneráveis (Transporte Aéreo)","c":"DIREITO DO CONSUMIDOR — TRANSPORTE AÉREO","co":"DIREITO DO CONSUMIDOR — TRANSPORTE AÉREO","g":["falta de assistência material e informacional","passageiros idosos ou com comorbidades"],"f":"Fundamentação para majoração ou reconhecimento de dano moral.","b":"Agrava a responsabilidade da companhia aérea a falha no dever de assistência material e informacional a passageiros idosos e com comorbidades. Caracteriza dano moral indenizável a permanência no aeroporto por longo período, desamparados.","e":["condição de vulnerabilidade (idoso, comorbidade)","ausência de assistência material/informação","longa espera no aeroporto"],"l":["prestação adequada de assistência material e informação"],"x":[]},{"id":"FUN-0022","t":"Cancelamento por manutenção extraordinária (Transporte Aéreo)","c":"DIREITO DO CONSUMIDOR — TRANSPORTE AÉREO","co":"DIREITO DO CONSUMIDOR — TRANSPORTE AÉREO","g":["voo cancelado sob alegação de manutenção não programada","discussão sobre fortuito externo x interno"],"f":"Fundamentação para afastar a excludente de responsabilidade e reconhecer o dever de indenizar.","b":"Caracteriza fortuito interno o cancelamento motivado por manutenção extraordinária da aeronave, não elidindo a responsabilidade objetiva. Afasta-se a limitação das Convenções de Varsóvia/Montreal para indenizações morais em transporte aéreo internacional (Tema 1240 do STF).","e":["cancelamento por problema técnico/manutenção","voo nacional ou internacional (dano moral)"],"l":["fortuito externo genuíno (ex: condições meteorológicas severas, fechamento de aeroporto)"],"x":[]},{"id":"FUN-0023","t":"Tempo de espera para descarregamento (Transporte Rodoviário de Cargas)","c":"DIREITO DO CONSUMIDOR — TRANSPORTE RODOVIÁRIO","co":"DIREITO DO CONSUMIDOR — TRANSPORTE RODOVIÁRIO","g":["cobrança de estadia por excesso de tempo de espera para carga/descarga","aplicação da Lei 11.442/2007"],"f":"Fundamentação para condenação ao pagamento de indenização por estadia.","b":"Perfaz o prazo máximo para carga e descarga 5 horas, contadas da chegada do veículo ao endereço de destino, após o qual é devida indenização ao TAC ou ETC (art. 11, § 5º, da Lei nº 11.442/2007). Não constitui a realização de aviso prévio condição para recebimento da indenização. Constitui o relatório de rastreamento meio idôneo para comprovação.","e":["espera superior a 5 horas","prova de chegada e saída (ex: rastreamento)"],"l":["espera inferior a 5 horas","ausência de prova do tempo de espera"],"x":[]},{"id":"FUN-0024","t":"Pane seca em transporte rodoviário de passageiros (Transporte Rodoviário)","c":"DIREITO DO CONSUMIDOR — TRANSPORTE RODOVIÁRIO","co":"DIREITO DO CONSUMIDOR — TRANSPORTE RODOVIÁRIO","g":["ônibus parado em rodovia por falta de combustível"],"f":"Fundamentação para reconhecimento de falha na prestação do serviço e dano moral.","b":"Constitui negligência na manutenção preventiva (fortuito interno) a interrupção da viagem por pane seca. Configura dano moral o atraso desproporcional com risco em rodovia.","e":["falta de combustível (pane seca)","atraso e exposição a risco"],"l":["interrupção por bloqueio imprevisível de rodovia"],"x":[]},{"id":"FUN-0025","t":"Legitimidade para reembolso de bilhete nominativo (Transporte Rodoviário)","c":"DIREITO DO CONSUMIDOR — TRANSPORTE RODOVIÁRIO","co":"DIREITO DO CONSUMIDOR — TRANSPORTE RODOVIÁRIO","g":["terceiro pleiteando reembolso de passagem em nome de outrem"],"f":"Fundamentação para reconhecer a ilegitimidade ativa.","b":"Pertence exclusivamente ao passageiro titular do bilhete nominativo a legitimidade para postular reembolso.","e":["bilhete emitido em nome de terceiro","pedido de reembolso"],"l":["cessão de crédito regular"],"x":[]},{"id":"FUN-0026","t":"Intempestividade do recurso inominado","c":"DIREITO PROCESSUAL CIVIL — RECURSOS","co":"DIREITO PROCESSUAL CIVIL — RECURSOS","g":["recurso interposto fora do prazo","discussão sobre contagem de prazo recursal"],"f":"Fundamentação para não conhecimento do recurso.","b":"Impõe o não conhecimento do recurso interposto de forma intempestiva. No microssistema dos Juizados Especiais, o prazo peremptório para interposição de Recurso Inominado é de dez dias úteis, contados da ciência efetiva da sentença (arts. 42 e 12-A da Lei nº 9.099/95).","e":["data da ciência da sentença","data da interposição","contagem em dias úteis"],"l":["erro na intimação","suspensão/interrupção do prazo"],"x":[]},{"id":"FUN-0027","t":"Deserção por ausência de preparo após indeferimento de gratuidade","c":"DIREITO PROCESSUAL CIVIL — RECURSOS","co":"DIREITO PROCESSUAL CIVIL — RECURSOS","g":["recurso interposto sem recolhimento de custas","indeferimento de assistência judiciária gratuita","prazo de 48 horas para recolhimento"],"f":"Fundamentação para não conhecimento do recurso por deserção.","b":"Deve o preparo recursal ser recolhido integralmente e comprovado nos autos nas 48 horas seguintes à interposição do Recurso Inominado (art. 42, § 1º, da Lei nº 9.099/95). Indeferida a Assistência Judiciária Gratuita, a inércia da parte em recolher as custas no prazo assinalado acarreta a deserção do recurso, sendo inadmissível a complementação intempestiva (Enunciado nº 80 do FONAJE).","e":["indeferimento de gratuidade","prazo de 48 horas","comprovação nos autos"],"l":["concessão de gratuidade","recolhimento tempestivo"],"x":[]},{"id":"FUN-0028","t":"Impossibilidade de parcelamento de custas nos Juizados Especiais","c":"DIREITO PROCESSUAL CIVIL — RECURSOS","co":"DIREITO PROCESSUAL CIVIL — RECURSOS","g":["pedido de parcelamento de custas recursais"],"f":"Fundamentação para rejeição do parcelamento.","b":"Incabível o parcelamento de custas recursais perante os Juizados Especiais, por incompatibilidade com o rito sumaríssimo (art. 8º, § 2º, da Lei nº 18.413/2014/PR e art. 42, § 1º, da Lei nº 9.099/95). Deve o recolhimento ocorrer de forma integral.","e":["pedido de parcelamento","custas recursais"],"l":["concessão de gratuidade da justiça"],"x":[]},{"id":"FUN-0029","t":"Inadmissibilidade de agravo de instrumento nos Juizados Especiais","c":"DIREITO PROCESSUAL CIVIL — RECURSOS","co":"DIREITO PROCESSUAL CIVIL — RECURSOS","g":["tentativa de interposição de agravo de instrumento"],"f":"Fundamentação para não conhecimento do recurso.","b":"Não possui o agravo de instrumento previsão no microssistema dos Juizados Especiais (Lei nº 9.099/95). Estabelece o art. 41 que o recurso cabível contra sentença é o recurso inominado. Afasta a especialidade do rito sumaríssimo a aplicação subsidiária do art. 1.015 do CPC.","e":["tentativa de agravo de instrumento","microssistema dos Juizados Especiais"],"l":["recurso inominado (recurso adequado)"],"x":[]},{"id":"FUN-0030","t":"Recurso inominado contra decisão terminativa de IDPJ (cabimento pela fungibilidade)","c":"DIREITO PROCESSUAL CIVIL — RECURSOS","co":"DIREITO PROCESSUAL CIVIL — RECURSOS","g":["decisão que indefere petição inicial e extingue o IDPJ","ausência de previsão de agravo de instrumento"],"f":"Fundamentação para conhecimento do recurso inominado.","b":"Possui natureza terminativa a decisão que indefere a petição inicial e extingue o IDPJ (art. 485, VI, CPC). No microssistema dos Juizados Especiais, impõe a ausência de previsão de agravo de instrumento o conhecimento do recurso inominado pela fungibilidade.","e":["decisão terminativa de IDPJ","indefimento de petição inicial"],"l":["decisão interlocutória"],"x":[]},{"id":"FUN-0031","t":"Inovação recursal","c":"DIREITO PROCESSUAL CIVIL — RECURSOS","co":"DIREITO PROCESSUAL CIVIL — RECURSOS","g":["dedução de pedido ou causa de pedir não veiculados na petição inicial","teses formuladas de forma inédita nas razões recursais"],"f":"Fundamentação para não conhecimento de teses inovadoras.","b":"Configura inovação recursal a dedução, em sede de razões recursais, de pedido ou causa de pedir não veiculados na petição inicial, sendo inadmissível sua apreciação nesta fase. Veda o ordenamento jurídico, em homenagem ao contraditório e à ampla defesa, o conhecimento de teses formuladas de forma inédita nas razões recursais.","e":["pedido ou causa de pedir não constante da inicial","tese inédita no recurso"],"l":["matérias de ordem pública (ex: incompetência absoluta)"],"x":[]},{"id":"FUN-0032","t":"Dialeticidade — repetição de argumentos da contestação","c":"DIREITO PROCESSUAL CIVIL — RECURSOS","co":"DIREITO PROCESSUAL CIVIL — RECURSOS","g":["recurso que repete argumentos já deduzidos","recurso formulado de forma genérica"],"f":"Fundamentação para não conhecimento do recurso ou para análise de mérito.","b":"Não enseja a mera repetição de argumentos da contestação, por si só, o não conhecimento do recurso, desde que suficientes as razões para impugnar os fundamentos da decisão atacada (STJ, REsp 1.665.741). Recursos formulados de maneira genérica, que não infirmem pormenorizadamente os fundamentos da decisão recorrida, ofendem o princípio da dialeticidade (art. 932, III, do CPC).","e":["argumentação genérica","falta de pormenorização dos fundamentos atacados"],"l":["argumentação específica e suficiente para infirmar a decisão"],"x":[]},{"id":"FUN-0033","t":"Dialeticidade — argumentação específica e clara","c":"DIREITO PROCESSUAL CIVIL — RECURSOS","co":"DIREITO PROCESSUAL CIVIL — RECURSOS","g":["recurso que apresenta razões específicas e claras","rebatimento pormenorizado dos fundamentos da sentença"],"f":"Fundamentação para conhecimento do recurso e análise de mérito.","b":"A parte recorrente expôs as suas razões recursais de maneira específica e clara, rebatendo os fundamentos da sentença de origem e requerendo a reforma pretendida, tendo, inclusive, consubstanciado as suas alegações em prova documental. Assim, a preliminar de ofensa ao princípio da dialeticidade deve ser rejeitada.","e":["argumentação específica","rebatimento claro dos fundamentos","prova documental"],"l":["argumentação genérica ou vaga"],"x":[]},{"id":"FUN-0034","t":"Perda superveniente do objeto","c":"DIREITO PROCESSUAL CIVIL — RECURSOS","co":"DIREITO PROCESSUAL CIVIL — RECURSOS","g":["acordo extrajudicial celebrado após sentença","resolução da lide na fase recursal"],"f":"Fundamentação para não conhecimento do recurso.","b":"Opera a celebração de acordo extrajudicial devidamente homologado a resolução do mérito e o esvaziamento da lide. Sobrevindo na fase recursal, impõe o não conhecimento do recurso por perda superveniente do objeto.","e":["acordo extrajudicial","homologação do acordo","fase recursal"],"l":["acordo não homologado ou ineficaz"],"x":[]},{"id":"FUN-0035","t":"Concessão de gratuidade mediante elementos probatórios","c":"DIREITO PROCESSUAL CIVIL — RECURSOS","co":"DIREITO PROCESSUAL CIVIL — RECURSOS","g":["pedido de assistência judiciária gratuita","elementos nos autos que demonstram vulnerabilidade econômica"],"f":"Fundamentação para concessão do benefício.","b":"Verificada nos autos a presença de elementos probatórios aptos a corroborar a presunção de vulnerabilidade econômica, impõe a concessão do benefício (art. 5º, LXXIV, CF, e art. 99, § 2º, do CPC).","e":["presença de elementos probatórios","presunção de vulnerabilidade econômica"],"l":["elementos concretos que evidenciem ausência dos pressupostos do benefício","não adotar corte de renda como critério legal universal; examinar a situação individual e o art. 99 do CPC"],"x":[{"campo":"Excludentes/limites","razao":"Retirada de referência a limite legal geral não identificado na fonte.","origem":"- ausência de elementos probatórios\n- renda acima do limite legal"}]},{"id":"FUN-0036","t":"Indeferimento de gratuidade por deficiência probatória","c":"DIREITO PROCESSUAL CIVIL — RECURSOS","co":"DIREITO PROCESSUAL CIVIL — RECURSOS","g":["pedido de gratuidade sem documentação comprobatória","descumprimento de comando judicial para apresentação de documentos"],"f":"Fundamentação para indeferimento do benefício.","b":"O indeferimento da gratuidade exige elementos que evidenciem a ausência de seus pressupostos. Antes da decisão, deve ser oportunizada a comprovação da insuficiência, conforme o art. 99, § 2º, do CPC. O descumprimento de determinação de apresentação de documentos deve ser examinado no contexto da presunção aplicável à pessoa natural e dos elementos dos autos.","e":["ausência de documentação","descumprimento de ordem judicial"],"l":["apresentação de documentação comprobatória"],"x":[{"campo":"Formulação-base","razao":"Separação entre deficiência documental e ausência dos pressupostos; adequação ao art. 99 do CPC.","origem":"Deve a concessão do benefício observar o binômio possibilidade–necessidade (STJ, EDcl no AREsp 348780/RS). Autoriza o indeferimento o descumprimento de comando judicial para apresentação de documentos comprobatórios (art. 98 do CPC)."}]},{"id":"FUN-0037","t":"Inadmissibilidade de mandado de segurança como sucedâneo recursal","c":"DIREITO PROCESSUAL CIVIL — RECURSOS","co":"DIREITO PROCESSUAL CIVIL — RECURSOS","g":["impetração de mandado de segurança contra decisão judicial","existência de recurso próprio cabível"],"f":"Fundamentação para não conhecimento do mandado de segurança.","b":"Inadmissível o mandado de segurança como sucedâneo recursal quando existente recurso próprio cabível (Súmula nº 267 do STF e art. 10 da Lei nº 12.016/2009). Cabe a defesa de bens atingidos por constrição judicial pela via dos embargos de terceiro (art. 674 do CPC). Encontra vedação no art. 18 do CPC a postulação de direito alheio em nome próprio.","e":["impetração de mandado de segurança","existência de recurso adequado"],"l":["ausência de recurso próprio","direito líquido e certo não passível de proteção por via recursal"],"x":[]},{"id":"FUN-0038","t":"Natureza integrativa dos embargos de declaração","c":"DIREITO PROCESSUAL CIVIL — RECURSOS","co":"DIREITO PROCESSUAL CIVIL — RECURSOS","g":["embargos de declaração por omissão, contradição ou obscuridade","tentativa de rediscussão de matéria decidida"],"f":"Fundamentação para acolhimento ou rejeição dos embargos, após exame separado da admissibilidade.","b":"Possuem os embargos de declaração natureza integrativa, voltados exclusivamente a sanar vícios de omissão, contradição, obscuridade ou erro material (arts. 48 da Lei nº 9.099/95 e 1.022, I a III, do CPC). Não servem como sucedâneo recursal para rediscussão de matéria decidida (STJ, EDcl no AgRg no AREsp 2622962/RJ).","e":["omissão, contradição, obscuridade ou erro material","vício na decisão"],"l":["rediscussão de questão já decidida"],"x":[{"campo":"Função no voto","razao":"A existência ou ausência do vício não se confunde automaticamente com conhecimento ou não conhecimento.","origem":"Fundamentação para conhecimento ou não conhecimento dos embargos."}]},{"id":"FUN-0039","t":"Acolhimento de embargos por erro de premissa fática","c":"DIREITO PROCESSUAL CIVIL — RECURSOS","co":"DIREITO PROCESSUAL CIVIL — RECURSOS","g":["erro na valoração do acervo probatório","contradição entre a prova e a fundamentação"],"f":"Fundamentação para acolhimento dos embargos com efeitos infringentes.","b":"Os embargos de declaração comportam acolhimento com efeitos infringentes quando a decisão embargada incorre em erro de premissa quanto à valoração do acervo probatório.","e":["erro de premissa fática","valoração incorreta da prova"],"l":["valoração adequada da prova"],"x":[]},{"id":"FUN-0040","t":"Incompetência do Juizado Especial — necessidade de perícia técnica","c":"DIREITO PROCESSUAL CIVIL — RECURSOS","co":"DIREITO PROCESSUAL CIVIL — RECURSOS","g":["alegação de incompetência por complexidade da causa","necessidade de perícia técnica"],"f":"Fundamentação para rejeição da preliminar de incompetência.","b":"Simples afirmação da necessidade de realizar prova complexa não afasta a competência do Juizado Especial, mormente quando não exauridos os instrumentos de investigação abarcados pela Lei nº 9.099/95 (Enunciado nº 2 da Turma Recursal Plena do TJPR). Verifica-se que a própria natureza da controvérsia afasta a utilidade da perícia pretendida, ressaltando-se que a controvérsia foi resolvida com base na análise documental, sendo suficiente para o deslinde da causa (art. 355, I, do CPC).","e":["alegação de complexidade","instrumentos de investigação disponíveis","análise documental suficiente"],"l":["prova efetivamente complexa e não disponível no microssistema"],"x":[]},{"id":"FUN-0041","t":"Recebimento e tramitação de Mandado de Segurança (Mandado de Segurança)","c":"DIREITO PROCESSUAL CIVIL — RECURSOS","co":"DIREITO PROCESSUAL CIVIL — RECURSOS","g":["processamento inicial de MS"],"f":"Fundamentação para análise de liminar e determinação de providências.","b":"Constitui o Mandado de Segurança ação destinada à proteção de direito líquido e certo contra ato ilegal ou abusivo praticado por autoridade pública (art. 5º, LXIX, CF). Exige a concessão de medida liminar a demonstração de fundamento relevante e do risco de ineficácia da medida (art. 7º, III, da Lei nº 12.016/09). Notifique-se a autoridade coatora para que preste as informações que entender necessárias, no prazo de 10 dias (art. 7º, I, da Lei nº 12.016/09). Dê-se ciência ao órgão de representação judicial da pessoa jurídica interessada, a fim de que, querendo, ingresse no feito (art. 7º, II, Lei nº 12.016/09). Na sequência, remetam-se os autos ao Ministério Público para manifestação, no prazo de 10 dias (art. 12, da Lei nº 12.016/09).","e":["impetração de MS","análise de liminar e rito"],"l":["uso como sucedâneo recursal (inadmissível)"],"x":[]},{"id":"FUN-0042","t":"Irrecorribilidade de decisão interlocutória nos Juizados Especiais","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["recurso contra decisão interlocutória","decisão que não encerra a fase processual"],"f":"Fundamentação para não conhecimento do recurso.","b":"Irrecorríveis são as decisões interlocutórias no rito dos Juizados Especiais, nos termos do art. 41 da Lei nº 9.099/95, que restringe o cabimento do recurso inominado às sentenças. Não acarreta a irrecorribilidade preclusão, permitindo reapreciação quando da interposição de recurso inominado contra futura sentença.","e":["natureza interlocutória da decisão","ausência de encerramento da fase"],"l":["sentença (decisão terminativa)"],"x":[]},{"id":"FUN-0043","t":"Desnecessidade de enfrentamento exaustivo de argumentos","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["alegação de omissão por não análise de todos os argumentos","decisão fundamentada em motivo suficiente"],"f":"Fundamentação para afastar nulidade por omissão.","b":"Não está o julgador obrigado a responder todas as questões suscitadas pelas partes, quando já tenha encontrado motivo suficiente para proferir decisão, devendo enfrentar apenas as questões capazes de infirmar a conclusão adotada (STJ, AgInt no AREsp 1037131/SP e art. 371 do CPC).","e":["decisão fundamentada","motivo suficiente para conclusão"],"l":["questão capaz de infirmar a conclusão não enfrentada"],"x":[]},{"id":"FUN-0044","t":"Formação do juízo — livre apreciação da prova","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["alegação de omissão por não análise minuciosa de argumentos","decisão baseada em elementos pertinentes e suficientes"],"f":"Fundamentação para manutenção da decisão.","b":"O magistrado não está obrigado a se pronunciar sobre cada argumento ou prova de forma minuciosa ou exaustiva, sendo suficiente que fundamente sua decisão com base nos elementos que considerar pertinentes e suficientes para a formação de seu convencimento (art. 371 do CPC). Consolidou-se no âmbito do STJ o entendimento de que o julgador possui o dever de enfrentar apenas as questões capazes de infirmar a conclusão adotada na decisão recorrida (STJ, AgInt no AREsp 1037131/SP).","e":["decisão suficientemente fundamentada","elementos pertinentes e suficientes"],"l":["omissão sobre questão capaz de infirmar a conclusão"],"x":[]},{"id":"FUN-0045","t":"Prequestionamento nos Juizados Especiais","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["embargos de declaração com finalidade exclusiva de prequestionamento","recurso extraordinário"],"f":"Fundamentação para examinar a finalidade de prequestionamento e a existência de vício, com admissibilidade analisada separadamente.","b":"A finalidade de prequestionamento deve ser examinada em conjunto com a existência dos vícios próprios dos embargos de declaração. A referência ao art. 1.025 do CPC não equivale a afirmar que todo fundamento implícito gera prequestionamento suficiente. O dispositivo prevê a inclusão dos elementos suscitados pelo embargante quando o tribunal superior reconhecer erro, omissão, contradição ou obscuridade.","e":["embargos com finalidade de prequestionamento","recurso extraordinário"],"l":["prequestionamento implícito já realizado"],"x":[{"campo":"Função no voto","razao":"Retirada de resultado automático de não conhecimento.","origem":"Fundamentação para não conhecimento dos embargos."},{"campo":"Formulação-base","razao":"Adequação da explicação do art. 1.025 do CPC; preservação das formulações antigas no registro de origem.","origem":"Enunciado 125 do FONAJE: nos Juizados Especiais não são cabíveis embargos declaratórios contra acórdão ou súmula com finalidade exclusiva de prequestionamento para fins de recurso extraordinário. Suficiente o prequestionamento implícito (art. 1.025 do CPC)."}]},{"id":"FUN-0046","t":"Prequestionamento — fundamentação clara e implícita","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["julgado que apresenta fundamentos claros","discussão sobre necessidade de prequestionamento expresso"],"f":"Fundamentação para afastar exigência de prequestionamento expresso.","b":"A finalidade de prequestionamento deve ser examinada em conjunto com a existência dos vícios próprios dos embargos de declaração. A referência ao art. 1.025 do CPC não equivale a afirmar que todo fundamento implícito gera prequestionamento suficiente. O dispositivo prevê a inclusão dos elementos suscitados pelo embargante quando o tribunal superior reconhecer erro, omissão, contradição ou obscuridade.","e":["fundamentos claros na decisão","dispositivos legais implícitos"],"l":["obscuridade na fundamentação"],"x":[{"campo":"Formulação-base","razao":"Adequação da explicação do art. 1.025 do CPC; preservação das formulações antigas no registro de origem.","origem":"Não é necessário o prequestionamento expresso de dispositivos legais quando o julgado apresenta de forma clara os fundamentos adotados, sendo suficiente o prequestionamento implícito, à luz do art. 1.025 do CPC (TJPR - Turma Recursal - 0016395-40.2025.8.16.0044 - Apucarana - Rel.: IRINEU STEIN JUNIOR - J. 02.12.2025)."}]},{"id":"FUN-0047","t":"Incompetência dos Juizados por necessidade de perícia grafotécnica","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["demanda que exige perícia grafotécnica","prova complexa que supera a competência do Juizado"],"f":"Fundamentação para declaração de incompetência absoluta.","b":"Atrai a necessidade de perícia grafotécnica por expert nomeado judicialmente a incompetência absoluta do Juizado Especial (art. 51, II, da Lei nº 9.099/95). A menor complexidade da causa para fixação da competência é aferida pelo objeto da prova e não em face do direito material (Enunciado 54 do FONAJE).","e":["perícia grafotécnica necessária","prova complexa"],"l":["prova simples ou documental"],"x":[]},{"id":"FUN-0048","t":"Rejeição de preliminar de incompetência por prova complexa","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["alegação de incompetência baseada em necessidade de prova complexa"],"f":"Fundamentação para manutenção da competência.","b":"Simples afirmação da necessidade de realizar prova complexa não afasta a competência do Juizado Especial, mormente quando não exauridos os instrumentos de investigação abarcados pela Lei nº 9.099/95 (Enunciado nº 2 da Turma Recursal Plena do TJPR).","e":["alegação de complexidade","instrumentos de investigação disponíveis"],"l":["prova efetivamente complexa e não disponível no microssistema"],"x":[]},{"id":"FUN-0049","t":"Competência territorial nos Juizados Especiais","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["discussão sobre foro competente","obrigação a ser satisfeita em local diverso do domicílio do réu"],"f":"Fundamentação para fixação da competência territorial.","b":"Poderá a demanda ser ajuizada no foro do lugar onde a obrigação deva ser satisfeita, configurando faculdade de escolha conferida ao credor (art. 4º, II, da Lei nº 9.099/95).","e":["local da satisfação da obrigação","domicílio do credor"],"l":["nenhum (faculdade da parte)"],"x":[]},{"id":"FUN-0050","t":"Conflito de competência — Banco do Brasil (matéria bancária)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["demanda contra Banco do Brasil envolvendo matéria bancária","discussão sobre competência entre Turmas Recursais"],"f":"Fundamentação para fixação da competência.","b":"Prevalece o critério ratione materiae sobre o ratione personae, em aplicação do princípio da especialidade (art. 7º da Resolução nº 466/2024-CSJES). Pertence a competência para matéria bancária às Turmas Recursais a que a Resolução nº 466/2024-CSJES a atribui, ainda que a parte seja sociedade de economia mista (Turma Recursal Plena do TJPR, 12.04.2021).","e":["matéria bancária","Banco do Brasil como parte"],"l":["matéria não bancária"],"x":[]},{"id":"FUN-0051","t":"Valor da causa e limite de alçada","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["discussão sobre valor da causa","pedido que incide sobre existência, validade ou rescisão do contrato"],"f":"Fundamentação para fixação do valor da causa ou declaração de incompetência.","b":"Em ações que visam exclusivamente a cobrança de parcelas inadimplidas, o valor da causa corresponde ao proveito econômico imediato. Havendo pedido que incida sobre a existência, validade ou rescisão do negócio jurídico, o valor da causa deve corresponder ao valor integral do contrato (art. 292, II, do CPC e Enunciado nº 39 do FONAJE). Ultrapassado o limite de quarenta salários-mínimos, impõe-se a declaração de incompetência.","e":["cobrança de parcelas","pedido de rescisão ou nulidade","limite de alçada"],"l":["cobrança isolada dentro do limite"],"x":[]},{"id":"FUN-0052","t":"Cerceamento de defesa — julgamento antecipado com prova suficiente","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["julgamento antecipado quando há prova suficiente","indeferimento de diligências protelatórias"],"f":"Fundamentação para manutenção da sentença.","b":"É o juiz o destinatário da prova, cabendo-lhe indeferir diligências protelatórias e julgar antecipadamente quando suficiente o acervo probatório (arts. 370 e 355, I, do CPC).","e":["prova suficiente para decisão","diligência protelatória"],"l":["prova insuficiente","diligência necessária e não protelatória"],"x":[]},{"id":"FUN-0053","t":"Cerceamento de defesa — ausência de necessidade de novas provas","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["alegação de cerceamento por não produção de novas provas","julgamento antecipado com prova suficiente"],"f":"Fundamentação para rejeição da preliminar de cerceamento.","b":"Não há que se falar em cerceamento de defesa sob o fundamento de necessária produção de novas provas, uma vez que, diante das circunstâncias fáticas e da natureza da lide, o julgamento antecipado mediante a prova constante dos autos se revelou suficiente para a formação do convencimento do Juízo (art. 371 do CPC).","e":["prova suficiente nos autos","circunstâncias fáticas claras"],"l":["prova insuficiente ou lacunosa"],"x":[]},{"id":"FUN-0054","t":"Cerceamento de defesa — supressão da fase instrutória","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["julgamento antecipado após indeferimento de prova","negativa de oitiva de testemunhas"],"f":"Fundamentação para nulidade da sentença.","b":"Configura cerceamento de defesa a conduta jurisdicional que julga antecipadamente o mérito, rejeitando a pretensão sob pretexto de insuficiência probatória (art. 373, I, do CPC), após ter indeferido requerimento tempestivo para produção de prova em audiência. No rito dos Juizados Especiais, independe a oitiva de testemunhas levadas à audiência de prévio arrolamento ou intimação (arts. 33 e 34 da Lei nº 9.099/95). Impõe a supressão dessa garantia a nulidade da sentença.","e":["indeferimento de prova","julgamento por insuficiência probatória","requerimento tempestivo"],"l":["prova manifestamente inútil ou protelatória"],"x":[]},{"id":"FUN-0055","t":"Nulidade por supressão de instância","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["decisão que aprecia questão não decidida na origem","acórdão que substitui o juízo de primeiro grau"],"f":"Fundamentação para nulidade do acórdão.","b":"Não pode o órgão revisor substituir o juízo de primeiro grau na apreciação originária de questões fáticas ou jurídicas que não foram previamente submetidas, instruídas e decididas na instância ordinária. Viola a prolação de acórdão com indevida supressão de instância o devido processo legal, consubstanciando nulidade absoluta passível de declaração de ofício a qualquer tempo, impondo o retorno dos autos à origem.","e":["questão não apreciada na origem","decisão originária sobre matéria nova"],"l":["matéria de ordem pública","causa madura"],"x":[]},{"id":"FUN-0056","t":"Ilegitimidade passiva — teoria da asserção","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["alegação de ilegitimidade passiva","verificação de responsabilidade pela descrição dos fatos"],"f":"Fundamentação para rejeição ou acolhimento da preliminar.","b":"Verifica a legitimidade de causa à luz da teoria da asserção, bastando verificar se os fatos descritos na petição inicial, caso comprovados, conduzem à responsabilidade da parte demandada.","e":["fatos descritos na inicial","possível responsabilidade da demandada"],"l":["fatos que não conduzem à responsabilidade da demandada"],"x":[]},{"id":"FUN-0057","t":"Legitimidade ativa — MEI e consumidor por equiparação","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["demanda proposta por Microempreendedor Individual","terceiro que sofre efeitos do defeito sem integrar relação contratual"],"f":"Fundamentação para reconhecimento de legitimidade ativa.","b":"Constitui a figura do Microempreendedor Individual (MEI) ficção jurídica tributária, não havendo distinção de personalidade jurídica em relação à pessoa física titular, que possui plena legitimidade ativa. Equiparado a consumidor, nos termos do art. 17 do CDC, o terceiro que sofre diretamente as consequências do defeito sem ter integrado formalmente a relação contratual.","e":["MEI como parte","terceiro que sofre efeitos do defeito"],"l":["terceiro que não sofre efeitos do defeito"],"x":[]},{"id":"FUN-0058","t":"Revelia — presunção relativa","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["réu revel","discussão sobre presunção de veracidade dos fatos"],"f":"Fundamentação para análise da prova mesmo com revelia.","b":"Gera a revelia presunção de veracidade dos fatos narrados na inicial, porém de caráter relativo, não dispensando a parte autora de demonstrar o fato constitutivo do seu direito (art. 373, I, CPC).","e":["revelia do réu","presunção de veracidade"],"l":["prova em contrário"],"x":[]},{"id":"FUN-0059","t":"Extinção prematura — inépcia da inicial e ausência injustificada","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["sentença terminativa por insuficiência documental","não comparecimento da autora à audiência"],"f":"Fundamentação para nulidade ou manutenção da sentença.","b":"Revela prematuridade a prolação de sentença terminativa por suposta insuficiência documental quando a exordial vier acompanhada de elementos mínimos aptos a justificar a demanda. Lado outro, enseja o não comparecimento da parte autora à audiência a extinção do feito (art. 51, I, da Lei nº 9.099/95), salvo apresentação de documento idôneo que ateste impossibilidade absoluta de locomoção.","e":["elementos mínimos na inicial","ausência injustificada à audiência"],"l":["documentação suficiente","justificativa válida para ausência"],"x":[]},{"id":"FUN-0060","t":"Responsabilidade objetiva do fornecedor (art. 14 do CDC)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["defeito na prestação de serviço","dano causado ao consumidor"],"f":"Fundamentação para condenação do fornecedor.","b":"O fornecedor de serviços responde, independentemente de culpa, pelos danos decorrentes de defeitos na prestação, nos termos do art. 14 do CDC. O afastamento da responsabilidade depende das hipóteses legais demonstradas, incluindo inexistência do defeito ou culpa exclusiva do consumidor ou de terceiro.","e":["defeito na prestação","dano ao consumidor","nexo causal"],"l":["inexistência do defeito demonstrada pelo fornecedor","culpa exclusiva do consumidor ou de terceiro, nos termos legais"],"x":[{"campo":"Formulação-base","razao":"O mero fato de terceiro não é, sozinho, a excludente prevista no art. 14, § 3º, do CDC.","origem":"Responde o fornecedor de serviços, independentemente de culpa, pela reparação dos danos causados aos consumidores por defeitos na prestação dos serviços (art. 14 do CDC). Excludentes: culpa exclusiva da vítima, fato de terceiro, inexistência do defeito (art. 14, § 3º, CDC)."},{"campo":"Excludentes/limites","razao":"Compatibilização com a formulação-base.","origem":"- culpa exclusiva da vítima\n- fato de terceiro\n- inexistência do defeito"}]},{"id":"FUN-0061","t":"Responsabilidade objetiva de concessionárias de serviço público","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["dano causado por concessionária de serviço público","discussão sobre excludentes de responsabilidade"],"f":"Fundamentação para condenação ou afastamento da responsabilidade.","b":"Fundada na teoria do risco administrativo (não integral), a responsabilidade objetiva de concessionárias de serviço público (art. 37, § 6º, CF, e art. 14 do CDC) admite afastamento mediante demonstração de excludente do nexo causal (STJ, REsp 1.849.987/SP).","e":["dano causado por concessionária","excludente de nexo causal"],"l":["fortuito externo genuíno"],"x":[]},{"id":"FUN-0062","t":"Responsabilidade solidária na cadeia de fornecimento","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["vício ou dano causado por empresa integrante da cadeia de fornecimento"],"f":"Fundamentação para condenação solidária.","b":"Respondem solidariamente as empresas que integram a mesma cadeia de fornecimento pelos vícios e danos causados ao consumidor (arts. 7º, parágrafo único, e 25, § 1º, do CDC).","e":["integração na cadeia de fornecimento","vício ou dano"],"l":["ausência de integração na cadeia"],"x":[]},{"id":"FUN-0063","t":"Inversão do ônus da prova — não dispensa demonstração mínima","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["inversão do ônus da prova em relação de consumo","alegação de direito sem demonstração mínima"],"f":"Fundamentação para exigência de prova mínima.","b":"Não dispensa a inversão do ônus da prova o consumidor da demonstração mínima do direito alegado (art. 6º, VIII, do CDC, e art. 373, I, CPC; STJ, AgInt no AREsp 1314821/SE).","e":["relação de consumo","inversão do ônus"],"l":["nenhum (exigência sempre presente)"],"x":[]},{"id":"FUN-0064","t":"Lucros cessantes — comprovação de extensão do dano","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["pretensão de reparação de lucros cessantes","discussão sobre comprovação da extensão do dano"],"f":"Fundamentação para análise de lucros cessantes.","b":"Em se tratando de pretensão de reparação de lucros cessantes, faz-se necessária a comprovação não apenas da existência do dano, como também de sua extensão. A configuração dos lucros cessantes exige mais do que a simples possibilidade de realização do lucro, requer probabilidade objetiva e circunstâncias concretas de que estes teriam se verificado sem a interferência do evento danoso, não podendo subsistir a condenação ao pagamento de lucros cessantes baseada em meras conjecturas e sem fundamentação concreta (STJ, REsp 1658754/PE).","e":["existência do dano","extensão do dano","probabilidade objetiva"],"l":["meras conjecturas","falta de fundamentação concreta"],"x":[]},{"id":"FUN-0065","t":"Requisito de configuração do dano moral","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["pedido de indenização por dano moral","discussão sobre presunção de dano"],"f":"Fundamentação para reconhecimento ou afastamento do dano moral.","b":"Configura dano moral a violação a direito da personalidade ou abalo à honra, imagem ou dignidade da pessoa. Não é presumido em todas as situações, exigindo análise do caso concreto, considerando a intensidade do dano e o contexto em que ocorreu.","e":["violação a direito da personalidade","abalo à honra, imagem ou dignidade","circunstâncias do caso"],"l":["mero dissabor ou aborrecimento","dano não comprovado"],"x":[]},{"id":"FUN-0066","t":"Primazia da realidade sobre a forma no encerramento da locação (Locação)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["cobrança de aluguéis após a desocupação efetiva, mas sem a entrega formal das chaves"],"f":"Fundamentação para limitar a cobrança de aluguéis até a efetiva desocupação e ciência do locador.","b":"Embora constitua a entrega das chaves, via de regra, o ato formal que encerra a locação, deve o princípio da primazia da realidade nortear as decisões. Quando demonstra a prova documental a ciência da desocupação e a retomada da posse pelo locador, configura a manutenção da cobrança para período posterior enriquecimento sem causa.","e":["desocupação efetiva do imóvel","ciência inequívoca do locador/imobiliária","ausência de entrega formal das chaves"],"l":["abandono do imóvel sem comunicação ao locador"],"x":[]},{"id":"FUN-0067","t":"Corte de serviço essencial a pedido do locador (Locação)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["locador solicita desligamento de água/luz durante a vigência do contrato para forçar desocupação ou pagamento"],"f":"Fundamentação para reconhecimento de ato ilícito e dever de indenizar.","b":"Configura conduta abusiva e ato ilícito a solicitação de interrupção de fornecimento de serviço essencial pelo locador, titular da conta, enquanto vigente o contrato de locação (arts. 186, 187 e 927 do CC). Não concede a obrigação de transferência de titularidade pelo locatário ao locador o direito de solicitar o corte.","e":["contrato de locação vigente","corte de serviço essencial a pedido do locador"],"l":["corte realizado pela concessionária por inadimplência do locatário (sem intervenção do locador)"],"x":[]},{"id":"FUN-0068","t":"Dever de guarda em estacionamento comercial (Furto em Estacionamento)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["furto de veículo ou pertences em estacionamento de estabelecimento comercial"],"f":"Fundamentação para responsabilização objetiva do estabelecimento.","b":"Assume o estabelecimento comercial o dever de guarda sobre os veículos de clientes e funcionários alocados em suas dependências, respondendo objetivamente pela reparação material (Súmula 130 do STJ). Comprovado que o bem subtraído era o meio de locomoção diário para o labor, ultrapassa a falha na segurança o aborrecimento e atrai compensação por danos morais.","e":["furto nas dependências do estabelecimento","comprovação de que o veículo era essencial para o labor (para o dano moral)"],"l":["estacionamento público sem controle de acesso ou proveito indireto pelo estabelecimento"],"x":[]},{"id":"FUN-0069","t":"Causa primária vs. causa secundária (Acidentes de Trânsito)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["colisão de veículos com múltiplas infrações","discussão sobre culpa concorrente x culpa exclusiva"],"f":"Fundamentação para atribuir a responsabilidade ao causador principal do acidente.","b":"Recai a responsabilidade civil sobre o condutor que pratica a causa primária e determinante do acidente, como a inobservância do dever de parada em cruzamento, colisão contra veículo estacionado ou conversão inadequada.","e":["identificação da conduta determinante para a colisão","inobservância de regra basilar de trânsito"],"l":["culpa concorrente efetiva (ambas as condutas foram determinantes para o resultado)"],"x":[]},{"id":"FUN-0070","t":"Extinção prematura do cumprimento de sentença (Execução)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["extinção da execução por não localização de bens sem esgotamento das buscas"],"f":"Fundamentação para anular a sentença extintiva e determinar o prosseguimento da execução.","b":"Constitui medida excepcional a extinção do cumprimento de sentença (art. 53, § 4º, Lei nº 9.099/95), dependendo da demonstração de esgotamento das diligências executórias e da prévia intimação do exequente. Configura prematuridade a ausência de intimação prévia. Devem ser processados os pedidos de utilização de ferramentas de pesquisa patrimonial (SNIPER, CNIB, SERASAJUD) antes da extinção.","e":["extinção sem intimação prévia","não esgotamento dos sistemas de busca de bens"],"l":["esgotamento de todas as vias de busca e inércia do credor após intimado"],"x":[]},{"id":"FUN-0071","t":"Astreintes e tutela específica (Execução)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["descumprimento de obrigação de fazer","discussão sobre valor da multa ou conversão em perdas e danos"],"f":"Fundamentação para manutenção da obrigação ou adequação da multa.","b":"Deve prevalecer, em sede de obrigação de fazer, a tutela específica, sendo a conversão em perdas e danos medida excepcional (art. 499 do CPC). Possui a multa cominatória natureza coercitiva, devendo o juízo adequar seu valor e fixar teto proporcional à obrigação principal (art. 537 do CPC).","e":["obrigação de fazer descumprida","necessidade de limitação/adequação das astreintes"],"l":["impossibilidade absoluta de cumprimento (conversão em perdas e danos)"],"x":[]},{"id":"FUN-0072","t":"Não configuração de litigância de má-fé pelo exercício de defesa (Litigância de Má-fé)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["pedido de condenação por litigância de má-fé baseado apenas na improcedência dos argumentos"],"f":"Fundamentação para afastar a condenação por litigância de má-fé.","b":"Exige a condenação prova robusta de dolo processual específico (art. 80, CPC). Não configura a mera improcedência dos argumentos automaticamente alteração da verdade dos fatos. Somente se aplica a penalidade quando comprovada culpa grave ou dolo (STJ, AgInt no AREsp 2.649.924/PE).","e":["exercício regular do direito de ação/defesa","ausência de dolo processual"],"l":["alteração intencional da verdade dos fatos ou uso de documento falso (ver tema complementar)"],"x":[]},{"id":"FUN-0073","t":"Configuração de litigância de má-fé por conduta desleal (Litigância de Má-fé - Complemento)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["alteração intencional da verdade ou omissão de fatos relevantes"],"f":"Fundamentação para condenação em multa por má-fé.","b":"Exige a condenação por litigância de má-fé análise criteriosa, pois envolve juízo de reprovabilidade da conduta processual. Verificado que a parte sustentou fatos destoantes do conjunto documental, omitiu circunstâncias relevantes e atribuiu à parte adversa conduta ilícita sem comprovação mínima, afronta tal postura os deveres de lealdade e boa-fé, justificando a incidência do art. 80, II e III, do CPC. Não configura equívoco ou interpretação extensiva, mas afirmações categóricas sem amparo probatório, aptas a induzir o juízo a erro.","e":["dolo processual","omissão intencional ou afirmação falsa"],"l":["mero equívoco material ou interpretação jurídica divergente"],"x":[]},{"id":"FUN-0074","t":"Atualização monetária e taxa legal — Lei nº 14.905/2024 (Correção Monetária e Juros)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS\nTEMA DE ORIGEM: Aplicação imediata da Lei nº 14.905/2024 (Correção Monetária e Juros)","g":["fixação de índices de correção monetária e juros de mora"],"f":"Fundamentação para aplicação dos novos parâmetros legais.","b":"A Lei nº 14.905/2024 alterou o regime civil de atualização monetária e juros. Na ausência de índice convencionado ou de lei específica, o art. 389 do CC prevê o IPCA. O art. 406 disciplina a taxa legal, calculada pela Selic com dedução do índice de atualização, observada a metodologia própria e o piso zero. Sua incidência deve respeitar a produção de efeitos do art. 5º e os períodos da obrigação; não deve ser justificada por uma qualificação genérica da lei como processual.","e":["obrigação submetida ao regime civil pertinente","identificação dos períodos de incidência","ausência de índice ou taxa convencionados ou regime específico que afaste a regra geral","observância da produção de efeitos e da metodologia da taxa legal"],"l":["obrigações com índices pactuados em contrato ou legislação específica diversa"],"x":[{"campo":"tema","razao":"Retirada do título que pressupunha aplicação imediata indistinta.","origem":"Aplicação imediata da Lei nº 14.905/2024 (Correção Monetária e Juros)"},{"campo":"Formulação-base","razao":"Correção da premissa de natureza processual e aplicação imediata aos processos em curso.","origem":"Possui a Lei nº 14.905/2024, ao alterar os arts. 389 e 406 do CC, natureza processual, com aplicação imediata aos processos em curso. Correção monetária pelo IPCA (art. 389, parágrafo único, CC). Juros de mora pela Taxa Selic, deduzido o percentual da correção monetária (art. 406, § 1º, CC)."},{"campo":"Elementos de aplicação","razao":"Inclusão das condições temporais e materiais.","origem":"- condenação pecuniária\n- processos em curso"}]},{"id":"FUN-0075","t":"Juros de mora em responsabilidade extracontratual","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["fixação do termo inicial dos juros em indenizações por ato ilícito extracontratual"],"f":"Fundamentação para fixação do termo inicial na data do evento danoso.","b":"Incidem os juros moratórios a partir do evento danoso em casos de responsabilidade extracontratual (Súmula 54 do STJ).","e":["responsabilidade extracontratual (ex: acidente de trânsito, fraude bancária)"],"l":["responsabilidade contratual (juros a partir da citação)"],"x":[]},{"id":"FUN-0076","t":"Nulidade por supressão de instância (Nulidades Processuais)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["recurso que traz questões não debatidas na origem","sentença que não apreciou todos os pedidos"],"f":"Fundamentação para anular a sentença ou não conhecer de parte do recurso.","b":"Não pode o órgão revisor substituir o juízo de primeiro grau na apreciação originária de questões fáticas ou jurídicas que não foram previamente submetidas, instruídas e decididas na instância ordinária. Viola a prolação de acórdão com indevida supressão de instância o devido processo legal, consubstanciando nulidade absoluta passível de declaração de ofício a qualquer tempo, impondo o retorno dos autos à origem.","e":["questão não decidida pelo juízo a quo","impossibilidade de aplicação da teoria da causa madura"],"l":["matéria de ordem pública","causa madura (art. 1.013, § 3º, CPC)"],"x":[]},{"id":"FUN-0077","t":"Cerceamento de defesa por supressão da fase instrutória (Nulidades Processuais)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["julgamento antecipado de improcedência por falta de provas, após indeferimento de instrução"],"f":"Fundamentação para anular a sentença por cerceamento de defesa.","b":"Configura cerceamento de defesa a conduta jurisdicional que julga antecipadamente o mérito, rejeitando a pretensão sob o pretexto de insuficiência probatória (art. 373, I, do CPC), após ter indeferido requerimento tempestivo para produção de prova em audiência. No rito dos Juizados Especiais, independe a oitiva de testemunhas levadas à audiência de prévio arrolamento ou intimação (arts. 33 e 34 da Lei nº 9.099/95). Impõe a supressão dessa garantia a nulidade da sentença.","e":["requerimento de prova oral/audiência","indeferimento pelo juiz","julgamento de improcedência por falta de provas"],"l":["prova documental suficiente para o deslinde do feito (prova oral inútil)"],"x":[]},{"id":"FUN-0078","t":"Cerceamento de defesa por ausência de intimação sobre defensor dativo (Nulidades Processuais)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["parte sem advogado que pede nomeação de dativo para recorrer e não é intimada da decisão"],"f":"Fundamentação para anular o trânsito em julgado e reabrir prazo.","b":"Viola as garantias constitucionais do contraditório a ausência de intimação da parte executada acerca da decisão que indefere pedido de nomeação de defensor dativo formulado para viabilizar interposição de recurso. Impede a impossibilidade de exercício do direito recursal por falha de comunicação a formação válida da coisa julgada, impondo a nulidade da certidão de trânsito em julgado e a reabertura de prazo.","e":["pedido de nomeação de defensor","ausência de intimação da decisão","trânsito em julgado indevido"],"l":["intimação regular realizada"],"x":[]},{"id":"FUN-0079","t":"Litisconsórcio facultativo vs. necessário (Competência - Complemento)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["demandas contra INSS (descontos associativos) ou Banco Central (PROAGRO)"],"f":"Fundamentação para fixação da competência (Estadual x Federal).","b":"Nas demandas de restituição por descontos associativos indevidos em benefício previdenciário, atua o INSS como mero órgão pagador, configurando litisconsórcio facultativo, fixando a competência da Justiça Estadual. Diversamente, nas ações sobre cobertura securitária do PROAGRO, detém o Banco Central do Brasil legitimidade passiva exclusiva ou em litisconsórcio necessário, atraindo a competência absoluta da Justiça Federal.","e":["descontos em benefício previdenciário (Justiça Estadual)","seguro PROAGRO (Justiça Federal)"],"l":["participação ativa do INSS na fraude (atrai competência Federal)"],"x":[]},{"id":"FUN-0080","t":"Legitimidade de sociedade de advogados nos Juizados Especiais","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["sociedade de advogados figurando como autora no JEC"],"f":"Fundamentação para reconhecer a legitimidade ativa.","b":"Possui a sociedade de advogados, desde que regularmente registrada na OAB e com receita adequada aos limites de microempresa, legitimidade para postular nos Juizados Especiais Cíveis (aplicação analógica do art. 8º, § 1º, II, da Lei nº 9.099/95).","e":["sociedade de advogados","enquadramento como ME/EPP"],"l":["receita superior ao limite de ME/EPP","irregularidade perante a OAB"],"x":[]},{"id":"FUN-0081","t":"Encerramento unilateral de conta corrente (Direito Bancário)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["cancelamento de conta sem aviso prévio","retenção de saldo"],"f":"Fundamentação para reconhecimento de ato ilícito e dano moral.","b":"Constitui direito subjetivo o encerramento de conta corrente, condicionado à notificação prévia do correntista. Configura ilícito civil o cancelamento abrupto, sem aviso e desacompanhado de prova contundente de suspeita de fraude. Agrava a conduta a retenção indevida de saldo disponível, gerando dano moral compensatório.","e":["encerramento sem notificação","ausência de prova de fraude","retenção de valores"],"l":["notificação prévia regular","bloqueio cautelar por suspeita fundada de fraude"],"x":[]},{"id":"FUN-0082","t":"Parcelamento automático do rotativo (Direito Bancário)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["parcelamento de fatura de cartão de crédito sem anuência (Resolução BACEN 4.549/2017)"],"f":"Fundamentação para declarar a abusividade do parcelamento.","b":"Condiciona o parcelamento automático do saldo devedor do rotativo à prova da prestação de informação prévia e da oferta de condições financeiras mais vantajosas ao consumidor. Ausente tal demonstração, configura abusividade a operação.","e":["parcelamento automático","ausência de informação prévia ou vantagem financeira"],"l":["comprovação de oferta de condições mais vantajosas e informação clara"],"x":[]},{"id":"FUN-0083","t":"Vício oculto de bem durável e vida útil (Vícios do Produto)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["defeito em produto durável após o fim da garantia contratual"],"f":"Fundamentação para responsabilização do fornecedor com base na vida útil.","b":"Em vício oculto de bem durável, responde o fornecedor pela falha estrutural com base na vida útil, mesmo após superada a garantia, impondo a devolução do bem e restituição do valor. Não é presumido o dano moral nessa hipótese.","e":["bem durável (ex: eletrodomésticos, veículos)","vício oculto manifestado dentro da vida útil esperada"],"l":["desgaste natural","decurso do prazo de vida útil"],"x":[]},{"id":"FUN-0084","t":"Falhas qualitativas em empreitada (Vícios do Serviço)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["serviço de construção/reforma com defeitos estéticos ou qualitativos, sem risco estrutural"],"f":"Fundamentação para determinar o abatimento do preço.","b":"Resolvem falhas qualitativas de execução, sem inutilização estrutural, pelo abatimento proporcional do preço.","e":["defeito de execução","ausência de risco à solidez e segurança"],"l":["inutilização da obra (enseja rescisão e perdas e danos)"],"x":[]},{"id":"FUN-0085","t":"Evento irrepetível e corrompimento de arquivos (Vícios do Serviço)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["perda de fotos/vídeos de eventos únicos (casamento, formatura)"],"f":"Fundamentação para condenação em perdas e danos e dano moral.","b":"Converte em perdas e danos a obrigação decorrente de entrega parcial por corrompimento de arquivos de momento irrepetível (ex.: fotografia de formatura/casamento). Gera efetiva compensação extrapatrimonial a frustração de legítima expectativa.","e":["evento único/irrepetível","perda ou corrompimento do material","frustração de expectativa"],"l":["recuperação integral dos arquivos"],"x":[]},{"id":"FUN-0086","t":"Adaptações de acessibilidade em condomínio (Direito Condominial)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["exigência de obras de acessibilidade após a entrega do empreendimento"],"f":"Fundamentação para afastar a responsabilidade da construtora.","b":"Desobrigam a construtora as deficiências de acessibilidade supervenientes à obra. Cabem ao condomínio as adequações em áreas comuns, por deliberação assemblear.","e":["norma de acessibilidade superveniente","áreas comuns"],"l":["descumprimento de normas de acessibilidade vigentes à época da aprovação do projeto"],"x":[]},{"id":"FUN-0087","t":"Seguro-fiança e tarifas contratuais em locação (Locação - Complemento)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["discussão sobre legalidade de renovação de seguro-fiança ou tarifa de boleto"],"f":"Fundamentação para reconhecer a legalidade das cobranças.","b":"Lícitas a renovação automática de seguro-fiança e a imposição de tarifa por pagamento em boleto, desde que existam previsão e solicitação expressas em contrato (pacta sunt servanda).","e":["previsão contratual expressa","anuência do locatário"],"l":["cobrança sem previsão contratual"],"x":[]},{"id":"FUN-0088","t":"Responsabilidade por avarias e laudos de vistoria (Locação - Complemento)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["cobrança de reparos no imóvel após desocupação"],"f":"Fundamentação para exigir prova dos danos.","b":"Subordina a responsabilidade do locatário por avarias no imóvel à apresentação de laudos de vistoria de entrada e saída.","e":["cobrança de reparos","necessidade de laudos comparativos"],"l":["ausência de laudo de entrada ou saída assinado pelas partes"],"x":[]},{"id":"FUN-0089","t":"Responsabilidade solidária de plataformas de comércio eletrônico (Comércio Eletrônico)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["produto não entregue ou entregue diferente do anunciado em marketplace"],"f":"Fundamentação para responsabilizar a plataforma/marketplace.","b":"Integram plataformas de comércio eletrônico a cadeia de consumo e respondem solidariamente pela ausência de entrega da mercadoria ou envio de produto diverso do anunciado.","e":["compra em marketplace","falha na entrega"],"l":["plataforma atuando como mera vitrine de classificados (sem intermediar pagamento/logística)"],"x":[]},{"id":"FUN-0090","t":"Financiamento ou diluição (DIS) sem prova de adesão (Instituição de Ensino)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["cobrança de parcelas de financiamento estudantil interno (ex: DIS - Diluição Solidária) sem anuência"],"f":"Fundamentação para declarar inexigibilidade e dano moral.","b":"Condiciona a adesão do aluno a programas de financiamento ou diluição (DIS) à prova expressa de anuência. Ausente a prova, configuram dano moral presumido a cobrança posterior e negativação.","e":["cobrança de financiamento/diluição","ausência de contrato assinado/anuência"],"l":["comprovação da adesão expressa do aluno"],"x":[]},{"id":"FUN-0091","t":"Êxito parcial e isenção de honorários (Honorários e Sucumbência)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["fixação de sucumbência em recurso inominado provido em parte"],"f":"Fundamentação para afastar a condenação em honorários.","b":"Considerando o parcial êxito recursal, descabe a condenação da parte recorrente ao pagamento de honorários advocatícios, em conformidade com o entendimento firmado no PUIL nº 3.874/PR (2023/0433250-2) e art. 55 da Lei nº 9.099/95.","e":["provimento parcial do recurso inominado"],"l":["recurso totalmente improvido (enseja condenação)"],"x":[]},{"id":"FUN-0092","t":"Êxito parcial — não condenação em honorários","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["recurso parcialmente provido","discussão sobre condenação em honorários"],"f":"Fundamentação para afastar condenação em honorários.","b":"Considerando o parcial êxito em seu recurso, deixa-se de condenar a parte recorrente ao pagamento de honorários advocatícios, em conformidade com o entendimento firmado no PUIL nº 3.874/PR (2023/0433250-2).","e":["provimento parcial do recurso"],"l":["recurso totalmente improvido"],"x":[]},{"id":"FUN-0093","t":"Desprovimento — condenação em honorários","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["recurso totalmente desprovido","sucumbência recursal"],"f":"Fundamentação para condenação em honorários.","b":"Em razão da sucumbência recursal, condena-se a recorrente ao pagamento de honorários advocatícios, os quais fixam-se em 20% sobre o valor atualizado da condenação, nos termos do art. 55 da Lei nº 9.099/95.","e":["recurso desprovido","sucumbência"],"l":["êxito parcial ou total do recurso"],"x":[]},{"id":"FUN-0094","t":"Prova oral — princípio da oralidade","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["recurso que visa alterar a valoração da prova testemunhal feita pelo juiz sentenciante"],"f":"Fundamentação para manter a sentença baseada na prova oral.","b":"Em razão do princípio da oralidade que norteia o procedimento dos Juizados Especiais (art. 2º, Lei nº 9.099/1995), a prova oral detém relevante papel na solução da controvérsia. A instrução mediante depoimento garante ao julgador contato direto com a formação da prova, conferindo especial deferência ao juízo de origem na avaliação dos fatos, salvo flagrante erro ou contradição.","e":["valoração de prova oral","ausência de erro flagrante do juiz sentenciante"],"l":["valoração manifestamente contrária à prova dos autos"],"x":[]},{"id":"FUN-0095","t":"Formação do convencimento e livre apreciação da prova (Princípios Probatórios)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["alegação de omissão por não análise de todos os argumentos ou provas da parte"],"f":"Fundamentação para afastar nulidade ou rejeitar embargos.","b":"Não está o magistrado obrigado a pronunciar sobre cada argumento ou prova de forma minuciosa ou exaustiva, sendo suficiente que fundamente sua decisão com base nos elementos que considerar pertinentes e suficientes para a formação de seu convencimento (art. 371 do CPC). Consolida o STJ que o julgador possui o dever de enfrentar apenas as questões capazes de infirmar a conclusão adotada na decisão recorrida (AgInt no AREsp 1037131/SP).","e":["decisão suficientemente fundamentada","não enfrentamento de tese irrelevante para o deslinde"],"l":["omissão sobre tese capaz de, em tese, infirmar a conclusão (art. 489, § 1º, IV, CPC)"],"x":[]},{"id":"FUN-0096","t":"Competência do relator para julgamento monocrático (Julgamento Monocrático)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["negativa de seguimento a recurso manifestamente inadmissível"],"f":"Fundamentação para decisão unipessoal.","b":"A decisão monocrática de inadmissibilidade deve observar o art. 932, III, do CPC e as regras regimentais aplicáveis ao órgão julgador. A Súmula nº 568 do STJ trata da atuação monocrática no próprio STJ e não substitui a verificação da competência regimental da Turma Recursal.","e":["recurso inadmissível (ex: intempestivo, deserto)"],"l":["recurso que preenche os pressupostos de admissibilidade"],"x":[{"campo":"Formulação-base","razao":"Separação do âmbito da súmula e do regimento efetivamente aplicável.","origem":"Nos termos do art. 932, III, do CPC, com amparo na Súmula nº 568 do STJ e na forma estabelecida no art. 182 do Regimento Interno deste Tribunal de Justiça, compete ao relator negar seguimento monocraticamente a recurso manifestamente inadmissível."}]},{"id":"FUN-0097","t":"Indeferimento de pedido de julgamento monocrático (Julgamento Monocrático)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["pedido da parte para julgamento monocrático sem súmula ou tese repetitiva"],"f":"Fundamentação para levar o feito a julgamento colegiado.","b":"O pedido de julgamento monocrático deve ser examinado conforme as hipóteses legais e regimentais aplicáveis. Ausente o enquadramento, o feito deve ser submetido ao órgão colegiado competente.","e":["pedido de julgamento unipessoal","ausência de precedente vinculante ou súmula"],"l":["existência de tese firmada em IRDR, IAC ou recurso repetitivo"],"x":[{"campo":"Formulação-base","razao":"Evita transformar uma descrição de hipótese em definição universal de entendimento dominante.","origem":"Não comporta acolhimento o pedido de julgamento monocrático quando ausente o enquadramento do feito nas hipóteses legais de decisão unipessoal. Deve o conceito de \"entendimento dominante\" pressupor a existência de súmula ou tese firmada em julgamento de casos repetitivos e incidentes (art. 932 do CPC). Ausente tal enquadramento, pertence ao colegiado a competência natural para o julgamento."}]},{"id":"FUN-0098","t":"Distinguishing - inaplicabilidade de precedente (Julgamento Monocrático)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["afastamento de precedente invocado pela parte por distinção fática"],"f":"Fundamentação para não aplicar tese ou precedente.","b":"A distinção fática ou jurídica relevante deve ser explicitada para demonstrar a inaplicabilidade do precedente invocado. A definição do órgão competente e da forma de julgamento depende das regras legais e regimentais pertinentes.","e":["invocação de precedente","distinção fática ou jurídica relevante"],"l":["identidade fática e jurídica com o precedente vinculante"],"x":[{"campo":"Formulação-base","razao":"O afastamento de um precedente não determina, sozinho, julgamento colegiado em toda hipótese.","origem":"Operado o distinguishing em razão da natureza distinta das atividades, marcos regulatórios ou circunstâncias fáticas, resta afastada a incidência do precedente invocado, impondo o julgamento do mérito pelo colegiado."}]},{"id":"FUN-0099","t":"Relação consumerista bancária (Relação de Consumo)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["incidência do CDC em contratos bancários"],"f":"Fundamentação para aplicação do CDC; exame separado dos requisitos de inversão do ônus da prova.","b":"Presentes consumidor e instituição financeira como fornecedora, aplica-se o CDC à relação bancária, conforme a Súmula 297 do STJ. A inversão do ônus da prova depende dos requisitos do art. 6º, VIII, do CDC. A responsabilidade por defeito do serviço deve ser examinada nos termos do art. 14, com identificação do dano, do nexo causal e das excludentes pertinentes.","e":["contrato bancário","destinatário final"],"l":["crédito tomado para fomento de atividade empresarial (salvo vulnerabilidade demonstrada)"],"x":[{"campo":"Função no voto","razao":"Relação de consumo não aciona automaticamente inversão.","origem":"Fundamentação para aplicação do CDC e inversão do ônus da prova."},{"campo":"Formulação-base","razao":"Separação entre classificação da relação, regra probatória e responsabilidade.","origem":"Presentes as figuras de consumidor e da instituição financeira como fornecedora (arts. 2º e 3º do CDC), a relação entre as partes é de natureza consumerista, nos termos da Súmula 297 do STJ, sendo aplicável o Código de Defesa do Consumidor. Nesse contexto, destaca-se a inversão do ônus da prova (art. 6º do CDC) e a responsabilidade objetiva da instituição financeira em caso de danos causados ao consumidor (art. 14 do CDC)."}]},{"id":"FUN-0100","t":"Relação consumerista — configuração (Relação de Consumo)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["demanda envolvendo consumidor e fornecedor"],"f":"Fundamentação para aplicação do CDC; exame separado dos requisitos de inversão do ônus da prova.","b":"Presentes consumidor e fornecedor, aplica-se o CDC à relação. A inversão do ônus da prova deve ser examinada pelos requisitos do art. 6º, VIII, e não decorre automaticamente da classificação consumerista. A fundamentação deve identificar os fatos a provar, o ônus pertinente e os elementos disponíveis, bem como os pressupostos de responsabilidade aplicáveis.","e":["presença de consumidor","presença de fornecedor"],"l":["relação não consumerista"],"x":[{"campo":"Função no voto","razao":"Compatibilização com o item bancário.","origem":"Fundamentação para aplicação do CDC."},{"campo":"Formulação-base","razao":"Separação entre classificação da relação, regra probatória e responsabilidade.","origem":"Presentes as figuras de consumidor e fornecedor (arts. 2º e 3º do CDC), a relação entre as partes é de natureza consumerista, o que demanda a aplicação do Código de Defesa do Consumidor. Nesse contexto, destaca-se a inversão do ônus da prova (art. 6º do CDC), que não afasta a necessidade de comprovação mínima pelo consumidor acerca do que alega como direito (art. 373, I, do CPC), bem como a responsabilidade objetiva do fornecedor em caso de danos causados ao consumidor (art. 14 do CDC)."}]},{"id":"FUN-0101","t":"Repetição do indébito em dobro (Repetição do Indébito)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["cobranças indevidas ocorridas antes e depois de 30/03/2021"],"f":"Fundamentação para aplicar a devolução simples e em dobro.","b":"A repetição em dobro deve ser examinada a partir do pagamento indevido e das condições do art. 42, parágrafo único, do CDC, inclusive o engano justificável. O EAREsp 676.608/RS adotou critério ligado à boa-fé objetiva e modulou a aplicação do entendimento para indébitos contratuais não públicos pagos após a publicação do acórdão, em 30/03/2021. A restituição referente ao período anterior exige exame do regime então aplicável. Compensação de valores e restituição de parcelas no curso da demanda dependem de fatos demonstrados no caso.","e":["pagamento indevido demonstrado","identificação das datas e da natureza da obrigação","exame da boa-fé objetiva e de eventual engano justificável","delimitação da modulação temporal pertinente"],"l":["engano justificável comprovado pelo fornecedor (afasta a dobra mesmo após 30/03/2021)"],"x":[{"campo":"Formulação-base","razao":"Uniformização do marco 30/03/2021 e retirada de fatos de um caso específico da fórmula geral.","origem":"Sobre o tema, o STJ firmou entendimento de que a repetição do indébito independe da natureza do elemento volitivo do fornecedor que realizou a cobrança indevida, revelando-se cabível quando a referida cobrança consubstanciar conduta contrária à boa-fé objetiva. Além disso, restou consignado que modulam-se os efeitos da presente decisão para que o entendimento quanto à restituição em dobro do indébito seja aplicado apenas a partir da publicação do acórdão, isto é, a partir de 31/03/2021 (STJ, EAREsp 676.608/RS). No caso em tela, considerando que não há prova da má-fé da instituição financeira e há cobranças indevidas anteriores e posteriores à data supracitada, a restituição das cobranças anteriores à 30/03/2021 devem ser realizadas de forma simples e a restituição das cobranças posteriores em dobro. Devida a restituição inclusive dos valores cobrados indevidamente no curso da demanda, com a devida compensação dos valores recebidos pela autora a título de saque e eventuais compras, a serem comprovados em sede de cumprimento de sentença."},{"campo":"Elementos de aplicação","razao":"O marco temporal não substitui os demais pressupostos da dobra.","origem":"- cobrança indevida continuada\n- marco temporal de 30/03/2021"}]},{"id":"FUN-0102","t":"Dano moral — configuração e comprovação (Dano Moral)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["pedido de indenização por dano moral","discussão sobre presunção de dano"],"f":"Fundamentação para reconhecimento ou afastamento do dano moral.","b":"A jurisprudência do STJ é firme no sentido de que a configuração do dano moral pressupõe uma grave agressão ou atentado a direito da personalidade, capaz de provocar sofrimentos e humilhações intensos, descompondo o equilíbrio psicológico do indivíduo por um período de tempo desarrazoado (STJ, AgInt no REsp 1655465/RS). Apesar de o CDC prever a inversão do ônus da prova (art. 6º, VIII), a sua aplicação não significa eximir o autor do ônus de apresentar prova mínima dos fatos constitutivos de seu direito, nos termos do art. 373, I, do CPC (STJ, AgInt no AREsp nº 2.298.281/RJ).","e":["violação a direito da personalidade","abalo à honra, imagem ou dignidade","prova mínima do dano"],"l":["mero dissabor ou aborrecimento","dano não comprovado"],"x":[]},{"id":"FUN-0103","t":"Dano moral — quantum indenizatório (Dano Moral)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["fixação do valor de indenização por dano moral"],"f":"Fundamentação para fixação do quantum.","b":"Sobre o quantum indenizatório, resta consolidado o entendimento de que a indenização por danos morais deve ser arbitrada com fulcro na razoabilidade e na proporcionalidade, de modo que seu valor não seja excessivo a ponto de gerar o enriquecimento ilícito do ofendido nem se mostre irrisório e, assim, estimule a prática danosa (STJ, AgInt no AREsp 1.352.950/MG). Tendo isso em vista, fixam-se em [valor] os danos morais, observando os princípios de proporcionalidade e razoabilidade, atendendo às finalidades punitiva e pedagógica da medida, evitando enriquecimento indevido.","e":["razoabilidade","proporcionalidade","funções compensatória e pedagógica"],"l":["valores excessivos ou irrisórios"],"x":[]},{"id":"FUN-0104","t":"Dano moral por inscrição em cadastro de inadimplentes (Dano Moral)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["inscrição ou manutenção indevida em cadastro de inadimplentes"],"f":"Fundamentação para reconhecimento de dano moral presumido.","b":"No tocante aos danos morais, conforme entendimento pacífico do STJ, o dano moral oriundo de inscrição ou manutenção indevida em cadastro de inadimplentes prescinde de prova, configurando-se in re ipsa, visto que é presumido e decorre da própria ilicitude do fato (AgInt no AREsp n. 1.745.021/SP).","e":["inscrição indevida","cadastro de inadimplentes"],"l":["inscrição legítima","exame de inscrição legítima preexistente e da Súmula 385 do STJ, quando pertinente"],"x":[{"campo":"Excludentes/limites","razao":"Inclusão de limite relevante ao dano presumido, sem alteração dos fatos de origem.","origem":"- inscrição legítima"}]},{"id":"FUN-0105","t":"Dano moral em serviço público (Dano Moral)","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["dano causado por interrupção ou falha em serviço público essencial"],"f":"Fundamentação para reconhecimento de dano moral.","b":"A jurisprudência do STJ é firme no sentido de que a configuração do dano moral pressupõe uma grave agressão ou atentado a direito da personalidade, capaz de provocar sofrimentos e humilhações intensos, descompondo o equilíbrio psicológico do indivíduo por um período de tempo desarrazoado (STJ, AgInt no REsp 1.655.465/RS). A concessionária responde objetivamente pelos danos causados aos consumidores pela interrupção do fornecimento, pois é seu dever legal ofertar um serviço adequado, eficiente, seguro e contínuo (art. 22, do CDC). Embora o CDC preveja a inversão do ônus da prova (art. 6º, VIII) e que se reconheça a essencialidade do serviço e a responsabilidade objetiva da concessionária, não fica o autor eximido de apresentar prova mínima dos fatos constitutivos de seu direito, nos termos do art. 373, I, do CPC (STJ, AgInt no AREsp nº 2.298.281/RJ).","e":["interrupção de serviço essencial","prova mínima do dano"],"l":["fortuito externo genuíno","dano não comprovado"],"x":[]},{"id":"FUN-0106","t":"Reserva de Margem Consignável (RMC) — legalidade e dever de informação","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS","g":["contratação de cartão de crédito consignado com retenção de RMC"],"f":"Fundamentação para reconhecer a legalidade da operação com ressalvas quanto ao dever de informação.","b":"A contratação de cartão de crédito consignado e a reserva de margem correspondente devem ser examinadas conforme a Lei nº 10.820/2003 e a regulamentação aplicável à data, ao benefício e à modalidade contratada. A previsão legal da modalidade não dispensa consentimento válido e informação clara sobre crédito rotativo, descontos e formas de pagamento. A contratação digital exige demonstração de integridade, autenticidade e manifestação de vontade.","e":["contratação de RMC","dever de informação clara"],"l":["ausência de manifestação de vontade válida ou informação adequada pode afetar a contratação","informação adequada afasta a alegação de falha informacional, sem funcionar como excludente da existência da modalidade","verificar legislação e regulamentação do período e do benefício"],"x":[{"campo":"Formulação-base","razao":"Retirada de referência estrutural a artigo da lei modificadora e de regulamento não atualizado individualmente.","origem":"A contratação de cartão de crédito consignado, com a correspondente retenção da Reserva de Margem Consignável (RMC), constitui modalidade de crédito lícita, amparada no art. 6º, § 5º, da Lei nº 13.172/2015 e regulamentada pelo INSS (art. 3º, III, da IN/INSS nº 39/2009), que autoriza a utilização de percentual exclusivo da margem consignável para pagamento do valor mínimo das faturas. Embora válida, tal contratação exige observância ao dever de informação clara e adequada (arts. 6º, III e IV, e 46 do CDC), de modo que o consumidor tenha plena ciência da natureza rotativa do crédito contratado. Quanto à forma, os contratos celebrados em ambiente digital possuem a mesma validade e eficácia jurídica dos instrumentos físicos. A contratação eletrônica não gera, por si só, a invalidade do acordo, desde que preservadas a integridade e a autenticidade da manifestação de vontade."},{"campo":"Excludentes/limites","razao":"Correção do significado da informação adequada no campo de limites.","origem":"- informação adequada prestada"}]},{"id":"FUN-0107","t":"Cartão consignado de benefício e reserva correspondente (RCC) — distinção entre modalidades","c":"OUTROS TEMAS JURÍDICOS","co":"OUTROS TEMAS JURÍDICOS\nTEMA DE ORIGEM: Cartão de crédito consignado (RCC) — distinção do empréstimo tradicional","g":["contratação de cartão de crédito consignado (RCC)","confusão com empréstimo consignado tradicional"],"f":"Fundamentação para reconhecer a legalidade com ressalvas sobre informação.","b":"Devem ser diferenciados o empréstimo consignado, o cartão de crédito consignado e o cartão consignado de benefício. A modalidade efetivamente contratada e a reserva de margem devem ser identificadas pela documentação e pela Lei nº 10.820/2003 e regulamentação aplicáveis à data. A informação ao consumidor deve esclarecer a dinâmica de pagamento e os descontos, sem presumir equivalência com empréstimo de parcelas fixas e prazo determinado.","e":["contratação de RCC","dever de informação clara sobre distinção"],"l":["ausência de manifestação de vontade válida ou informação adequada pode afetar a contratação","informação adequada afasta a alegação de falha informacional, sem funcionar como excludente da existência da modalidade","verificar legislação e regulamentação do período e do benefício"],"x":[{"campo":"tema","razao":"Distinção entre cartão de crédito consignado e cartão consignado de benefício.","origem":"Cartão de crédito consignado (RCC) — distinção do empréstimo tradicional"},{"campo":"Formulação-base","razao":"Evita tratar RMC e RCC como nomes intercambiáveis da mesma modalidade.","origem":"A contratação de cartão de crédito consignado (RCC) constitui modalidade de crédito lícita, amparada no art. 6º, § 5º, da Lei nº 13.172/2015 e regulamentada pelo INSS (art. 3º, III, da IN/INSS nº 39/2009). Diversamente do empréstimo consignado tradicional, o RCC opera mediante desconto automático apenas do valor mínimo da fatura diretamente no benefício previdenciário do contratante, sendo facultado ao titular complementar o pagamento até o total da fatura. Por apresentar características próprias e dinâmica diversa do empréstimo consignado convencional, a distinção entre essas duas modalidades deve ser clara e compreensível ao consumidor no momento da contratação, especialmente quando se trata de pessoa idosa e hipossuficiente que, ao buscar crédito, naturalmente espera operação com parcelas fixas e prazo certo de quitação."},{"campo":"Excludentes/limites","razao":"Correção do significado da informação adequada no campo de limites.","origem":"- informação adequada prestada"}]}];
